/**
 * Generated by scaffold-listing-primitives. `data-component="row-select"`.
 *
 * The bulk-select checkbox — one in the header (select-all) and one per row.
 * Pair with useRowSelection; see its header for the wiring.
 */
import { useEffect, useRef } from 'react';

export interface RowSelectProps {
  checked: boolean;
  onChange: () => void;
  /** Header checkbox only: some-but-not-all rows selected. */
  indeterminate?: boolean;
  disabled?: boolean;
  label?: string;
  testId: string;
}

export function RowSelect({ checked, onChange, indeterminate, disabled, label, testId }: RowSelectProps) {
  const ref = useRef<HTMLInputElement>(null);

  // `indeterminate` is a DOM property with no HTML attribute, so React cannot set
  // it declaratively — it has to be assigned after render.
  useEffect(() => {
    if (ref.current) ref.current.indeterminate = Boolean(indeterminate) && !checked;
  }, [indeterminate, checked]);

  return (
    <input
      ref={ref}
      type="checkbox"
      className="row-check"
      checked={checked}
      disabled={disabled}
      onChange={onChange}
      aria-label={label ?? 'Select row'}
      data-testid={testId + '-select'}
    />
  );
}
